/**
 * indic-transliterator — Public API
 *
 * Pure functions (no React required):
 *   transliterate(text, script)  → string
 *   getSuggestions(word, script) → string[]
 *   toDevanagari(text)           → string
 *   convertScript(text, script)  → string
 *   SCRIPTS                      → string[]
 *
 * React hook (requires React ≥ 16.8):
 *   useTransliterate(options)    → { value, setValue, output, suggestions, script, setScript }
 *
 * Supported scripts:
 *   'devanagari' | 'bengali' | 'gurmukhi' | 'gujarati' | 'odia' |
 *   'tamil' | 'telugu' | 'kannada' | 'malayalam' | 'urdu' | 'kashmiri'
 */

export {
  transliterate,
  getSuggestions,
  toDevanagari,
  convertScript,
  romanize,
  SCRIPTS,
} from './engine.js';

// ─────────────────────────────────────────────────────────────────────────────
//  React hook  (tree-shaken away if React is not present)
// ─────────────────────────────────────────────────────────────────────────────

import { useState, useMemo } from 'react';
import { transliterate, getSuggestions } from './engine.js';

/**
 * useTransliterate — stateful React hook for phonetic transliteration.
 *
 * Manages the English input value, produces the transliterated output for the
 * full text, and returns an up-to-date suggestions array for the word that is
 * currently being typed (the last word in the input).
 *
 * @param {object}  [opts]
 * @param {string}  [opts.script='devanagari'] - Initial target script
 * @param {number}  [opts.maxSuggestions=6]    - Max suggestions to return (1–6)
 * @param {string}  [opts.initialValue='']     - Pre-filled English text
 *
 * @returns {{
 *   value:       string,    — current English input value
 *   setValue:    Function,  — setter for the English input (like useState setter)
 *   output:      string,    — full transliterated text (updates on every keystroke)
 *   suggestions: string[],  — variants for the word currently being typed
 *   script:      string,    — active script key
 *   setScript:   Function,  — change the target script at runtime
 * }}
 *
 * @example — bare usage (controlled input)
 *   const { value, setValue, output, suggestions } = useTransliterate({ script: 'tamil' });
 *   // value     → '' (what the user types in Roman)
 *   // output    → '' (live transliterated result)
 *   // suggestions → [] (variants for the last typed word)
 *
 * @example — pick a suggestion
 *   // Replace the last word in value with the chosen suggestion, then update.
 *   function pickSuggestion(suggestion) {
 *     const words = value.trimEnd().split(' ');
 *     words[words.length - 1] = suggestion;  // or map back to Roman as needed
 *     setValue(words.join(' ') + ' ');
 *   }
 */
export function useTransliterate({
  script: initialScript = 'devanagari',
  maxSuggestions = 6,
  initialValue = '',
} = {}) {
  const [value, setValue] = useState(initialValue);
  const [script, setScript] = useState(initialScript);

  // Full transliterated output for the entire input text
  const output = useMemo(() => transliterate(value, script), [value, script]);

  // Suggestions for the last word the user is currently typing.
  // Trailing whitespace means the word is committed — clear suggestions.
  const suggestions = useMemo(() => {
    if (/\s$/.test(value)) return [];
    const lastWord = value.split(/\s+/).filter(Boolean).pop() || '';
    if (lastWord.length < 2) return [];
    if (/\d/.test(lastWord)) return [];  // skip words containing digits
    return getSuggestions(lastWord, script).slice(0, maxSuggestions);
  }, [value, script, maxSuggestions]);

  return { value, setValue, output, suggestions, script, setScript };
}
